				\begin{document}$$\begin{array}{*{20}c} {AvgP\left( p \right) = \frac{1}{{\left| {{GT}_{p} } \right|}}\mathop \sum \limits_{i}^{{{TX}_{p} }} (P@i \times rel\left( i \right))} \\ \end{array}$$\end{document}AvgPp=1GTp∑iTXp(P@i×reli)
